scwin.fireOver = function(id) {
    var node = WebSquare.wUnit.getDomById($p.id + id)
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.__checkHtml = function() {
    return WebSquare.wUnit.getJq("#wq_uuid_3_tooltip").html();
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.fireOver('wq_uuid_3_cell_0_3')");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wq_uuid_3_tooltip').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkHtml() == 'name1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
